sys_script_include.script:
var AssetLoanUtils = Class.create();
AssetLoanUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    // Returns true/false whether a given asset sys_id is currently available
    isAssetAvailable: function(assetSysId) {
        var asset = new GlideRecord("x_2228927_asset_0_asset");
        if (!asset.get(assetSysId)) {
            return false;
        }
        return asset.status == 'available';
    },
    // Server-callable version for GlideAjax (client scripts / widgets)
    ajaxIsAssetAvailable: function() {
        var assetSysId = this.getParameter('sysparm_asset_id');
        return this.isAssetAvailable(assetSysId).toString();
    },
    // Returns a GlideRecord query of all currently available assets,
    // optionally filtered by category
    getAvailableAssets: function(category) {
        var asset = new GlideRecord("x_2228927_asset_0_asset");
        asset.addQuery('status', "available");
        if (category) {
            asset.addQuery('category', category);
        }
        asset.query();
        return asset;
    },
    // Counts how many assets are currently on loan (useful for a dashboard/widget later)
    getOnLoanCount: function() {
        var assets = new GlideAggregate("x_2228927_asset_0_asset");
        assets.addQuery("status", "on_loan");
        assets.addAggregate('COUNT');
        assets.query();
        if (assets.next()) {
            return assets.getAggregate('COUNT');
        }
        return 0;

    },
    type: 'AssetLoanUtils'
});
